// Junta os leads pendentes num lembrete só
const leads = $input.all().map(i => i.json).filter(l => l.id);
if (!leads.length) return [];
const fmt = l => {
  const itens = (typeof l.itens === 'string' ? JSON.parse(l.itens) : l.itens || []).map(i => i.quantidade + 'x ' + i.produto).join(', ');
  const horas = Math.round((Date.now() - new Date(l.created_at).getTime()) / 36e5);
  return '• ' + (l.nome || 'Sem nome') + (l.cidade ? ' (' + l.cidade + ')' : '') + ' há ' + horas + 'h\n  ' + (itens || 'orçamento geral') +
    (l.telefone ? '\n  https://wa.me/' + l.telefone : '');
};
const texto = '⏰ *Pedidos sem resposta há mais de 24h* (' + leads.length + ')\n\n' + leads.map(fmt).join('\n\n') +
  '\n\nQuando responder, marque o status como "respondido" na tabela leads_bemestar.';
return [{ json: { texto, ids: leads.map(l => l.id) } }];
